readonly struct Key : IEquatable<Key>
{
    public readonly string Region; public readonly int Id;
    public bool Equals(Key o) => Region == o.Region && Id == o.Id;
    public override bool Equals(object? o) => o is Key k && Equals(k);
    public override int GetHashCode() => HashCode.Combine(Region, Id);
}

struct Point : ___<Point>
{
    public int X, Y;
    public bool Equals(Point o) => X == o.X && Y == o.Y;
    public override bool Equals(object? o) => o is Point p && ___(p);
    public override int GetHashCode() => HashCode.Combine(X, Y);
}

